(()=>{'use strict';const frame=document.getElementById('business-login-frame');if(!frame)return;window.addEventListener('message',event=>{if(event.origin!=='https://office.mowmatter.com'||event.source!==frame.contentWindow)return;const data=event.data;if(!data||typeof data!=='object')return;if(data.type==='mm-business-login-height'&&Number.isFinite(data.height))frame.style.height=Math.min(1600,Math.max(300,data.height+32))+'px';else if(data.type==='mm-business-signed-in')location.assign('https://office.mowmatter.com/');else if(data.type==='mm-business-login-provider'&&['google','facebook'].includes(data.provider))location.assign('https://office.mowmatter.com/login.html?signin='+data.provider+'&launch_updates='+(data.launchUpdates===false?'0':'1'))})})();
